/**
 * @fileoverview Supabase database schema types for Nanobanna Pro
 *
 * This file contains TypeScript type definitions for the Neon PostgreSQL database schema including:
 * - Core entity types with RLS policies (User, Design, BrandProfile, UsageMetric, ReferenceImage)
 * - User preferences and configuration (UserPreferences)
 * - Aggregated statistics (UserStats)
 * - Request/Response types for API operations (Create*, Update*, Upload*)
 * - Authentication metadata (SignUpMetadata, UsernameValidation)
 *
 * All tables use Row Level Security (RLS) with policies based on auth.uid().
 * Database fields use snake_case naming convention (e.g., user_id, created_at).
 *
 * @see {@link ./ai.ts} for BrandProfile app state version (camelCase, no DB fields)
 * @see {@link ../services/database.ts} for database service implementations
 * @see {@link ../context/AuthContext.tsx} for authentication context
 */

export interface User {
  id: string; // This matches auth.users.id
  email: string;
  // Keep for backward compatibility
  full_name?: string;
  // NEW FIELDS - split name
  first_name?: string;
  last_name?: string;
  username?: string; // Unique handle, displayed as @username
  avatar_url?: string;
  credits: number;
  is_pro: boolean;
  created_at: string;
  updated_at: string;
}

export interface Design {
  id: string;
  user_id: string;
  title: string;
