/**
 * Brand profile for database persistence (stored in Supabase/PostgreSQL).
 *
 * ⚠️ IMPORTANT: This is the DATABASE schema version of BrandProfile for persistence.
 * There is also an APP STATE version in `ai.ts` with different fields used for React state.
 *
 * **Key Differences from App State Version:**
 * - Uses snake_case (e.g., `logo_url`, `style_keywords`) per PostgreSQL convention
 * - Includes database identifiers (`id`, `user_id`, `name`, `is_active`)
 * - Includes database timestamps (`created_at`, `updated_at` as ISO strings)
 * - `fonts` array is OPTIONAL here (required in app state)
 * - Has additional fields: `reference_images`, `is_active`
 *
 * **Data Flow:**
 * ```
 * Database (BrandProfile) → Load → Transform → App State (BrandProfile)
 *                                              ↓
 *                                         User edits
 *                                              ↓
 *                                    Transform → Save → Database (BrandProfile)
 * ```
 *
 * **Row Level Security:**
 * This table has RLS policies enabled:
 * - `SELECT`: Users can only read their own profiles (`user_id = auth.uid()`)
 * - `INSERT/UPDATE/DELETE`: Users can only modify their own profiles
 *
 * **When to Use:**
 * - Database service operations (CRUD)
 * - Supabase queries
 * - API request/response payloads
 * - Persistence layer
 *
 * **When NOT to Use:**
 * - React component props (use `ai.ts` version)
 * - AIContext state management (use `ai.ts` version)
 * - Passing to AI generation services (use `ai.ts` version)
 *
 * @example
 * ```typescript
 * // Saving to database
 * const appProfile: BrandProfile = brandProfile; // from AIContext
 * const dbProfile: BrandProfile = {
 *   id: existingId || nanoid(),
 *   user_id: userId,
 *   name: 'My Brand',
 *   colors: appProfile.colors,
 *   fonts: appProfile.fonts,
 *   style_keywords: appProfile.styleKeywords,
 *   logo_url: appProfile.logoUrl,
 *   industry: appProfile.industry,
 *   target_audience: appProfile.targetAudience,
 *   reference_images: [],
 *   is_active: true,
 *   version: appProfile.version,
 *   created_at: new Date().toISOString(),
 *   updated_at: new Date().toISOString()
 * };
 * await database.saveBrandProfile(dbProfile);
 * ```
 *
 * @see {@link ../types/ai.ts} BrandProfile for app state version (camelCase, no DB fields)
 * @see {@link ../services/database.ts} for database operations
 * @see {@link ../services/brandEngine.ts} for transformation logic
 */
export interface BrandProfile {
  /** UUID primary key */
  id: string;
  /** Foreign key to auth.users.id (enforced by RLS) */
  user_id: string;
  /** User-friendly name for this brand profile (e.g., "Tech Startup Brand", "Personal Brand") */
  name: string;
  /** Brand color palette with semantic usage tags (required, must have at least one) */
  colors: Array<{ hex: string; name: string; usage: 'primary' | 'accent' | 'background' }>;
  /** Typography choices with semantic usage (optional in database, required in app state) */
  fonts?: Array<{ name: string; usage: 'heading' | 'body' }>;
  /** Style descriptors for AI generation (e.g., ["modern", "minimalist", "tech"]) */
  style_keywords?: string[];
  /** URL to brand logo image stored in Supabase Storage */
  logo_url?: string;
  /** Industry/sector for context (e.g., "SaaS", "Finance", "E-commerce") */
  industry?: string;
  /** Target audience description (e.g., "B2B decision makers", "Gen Z consumers") */
  target_audience?: string;
  /** Array of reference image URLs for visual style consistency */
  reference_images?: string[];
  /** Whether this profile is currently active (users can have multiple profiles but only one active) */
  is_active: boolean;
  /** Schema version number for future migrations */
  version: number;
  /** ISO 8601 timestamp of creation */
  created_at: string;
  /** ISO 8601 timestamp of last update (automatically managed by Supabase) */
  updated_at: string;
}

